<template>    <div        :class="['calendar-cell', {'_clickable': isClickable}]"        @click="$emit('popup:open', dayData)"    >        <div            class="inner"            :class="props.dayData.content?.length && 'cursor-pointer'"            v-if="props.dayData"        >            <div class="day-number">                {{ props.dayData?.dayInfo.dayIndex }}            </div>            <div                class="content"                v-if="dayData?.content?.length"            >                <div                    v-for="serial in serials"                    :key="serial.id"                    class="serial"                    :style="{                        backgroundImage: `url(${preview(serial)})`,                    }"                >                </div>            </div>        </div>    </div></template><script lang="ts" setup>// Importsimport {useRuntimeConfig} from "#app";import {computed} from "#imports";import type {TDay} from "~/appModules/calendar/calendarTypes";// Typesinterface IMappedSerial {    id: string;    title: string;}// Composablesconst config = useRuntimeConfig();// Propsconst props = defineProps<{    dayData: TDay;}>();// Computedconst isCurrentDay = computed((): boolean => {    return false;});// Фильтруем повторяющиеся сериалыconst serials = computed((): IMappedSerial[] => {    return (props.dayData?.content || []).reduce((acc: any, serial: any) => {        if (acc.some((item: any) => item.id === serial.serial._id)) {            return acc;        }        return [...acc, {id: serial.serial._id, title: serial.serial.title}];    }, []);});const isClickable = computed((): boolean => {    return Boolean(props.dayData?.content?.length);});// Methodsconst preview = (serial: IMappedSerial): string => {    return `${config.public.cdnUrl}/serials/${serial.id}.jpg`;};</script><style lang="scss" scoped>.calendar-cell {    height: 100%;    pointer-events: none;    &._clickable {        cursor: pointer;        pointer-events: all;    }}.inner {    position: relative;    width: 100%;    height: 100%;    background-color: $color2;    border-radius: 10px;    overflow: hidden;}.day-number {    position: absolute;    top: 10px;    left: 10px;    width: 30px;    height: 30px;    background-color: $color1;    color: $color5;    border-radius: 100%;    display: flex;    align-items: center;    justify-content: center;    text-align: center;    font-size: 12px;}.content {    height: 100%;    display: flex;    flex-direction: column;}.serial {    height: 100%;    background-size: cover;}</style>